                raw_excerpt=_clip(resp.text, 2048),
            ) from exc
        try:
            text = data["content"][0]["text"]
        except (KeyError, IndexError, TypeError):
            text = ""
        if not text:
            raise ProviderError(
                "empty_response",
                "anthropic produced no extractable text",
                http_status=resp.status_code,
                raw_excerpt=_clip(json.dumps(data), 2048),
            )
